import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib

app = Flask(__name__)
UPLOAD_DIR = '/tmp/reports'
TEMPLATE_DIR = '/opt/app/templates'

os.makedirs(UPLOAD_DIR, exist_ok=True)

def get_template_path(template_name):
    """Resolve template path - supports subdirectories for org-specific templates"""
    # Normalize but allow subdirectory traversal for multi-tenant template resolution
    resolved = os.path.normpath(os.path.join(TEMPLATE_DIR, template_name))
    return resolved

def render_latex_report(template_path, variables):
    """Render a LaTeX template with variable substitution and compile to PDF"""
    with open(template_path, 'r') as f:
        content = f.read()

    # Substitute variables into template
    for key, value in variables.items():
        content = content.replace('{{' + key + '}}', value)

    # Write to temp file and compile
    work_dir = tempfile.mkdtemp(prefix='latex_')
    tex_path = os.path.join(work_dir, 'report.tex')

    with open(tex_path, 'w') as f:
        f.write(content)

    # Compile LaTeX to PDF
    result = subprocess.run(
        ['pdflatex', '-interaction=nonstopmode', '-output-directory', work_dir, tex_path],
        capture_output=True, timeout=30, cwd=work_dir
    )

    pdf_path = os.path.join(work_dir, 'report.pdf')
    if os.path.exists(pdf_path):
        return pdf_path
    return None

@app.route('/api/v1/report/generate', methods=['POST'])
def generate_report():
    """Generate PDF report from template with user-supplied variables"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    template_name = data.get('template', 'default/quarterly.tex')
    variables = data.get('variables', {})
    org_id = data.get('org_id', 'default')

    # Validate org_id format
    if not org_id.isalnum():
        return jsonify({'error': 'Invalid org_id'}), 400

    # Resolve template
    template_path = get_template_path(template_name)

    if not os.path.exists(template_path):
        return jsonify({'error': 'Template not found'}), 404

    # Generate report
    pdf_path = render_latex_report(template_path, variables)

    if pdf_path:
        return send_file(pdf_path, mimetype='application/pdf', as_attachment=True,
                        download_name=f'report_{org_id}.pdf')
    return jsonify({'error': 'Compilation failed'}), 500

@app.route('/api/v1/report/preview', methods=['POST'])
def preview_report():
    """Preview rendered LaTeX source before compilation"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    template_name = data.get('template', 'default/quarterly.tex')
    variables = data.get('variables', {})

    template_path = get_template_path(template_name)

    if not os.path.exists(template_path):
        return jsonify({'error': 'Template not found'}), 404

    with open(template_path, 'r') as f:
        content = f.read()

    for key, value in variables.items():
        content = content.replace('{{' + key + '}}', value)

    return jsonify({'rendered': content, 'template_used': template_path})

@app.route('/api/v1/templates', methods=['GET'])
def list_templates():
    """List available templates"""
    templates = []
    for root, dirs, files in os.walk(TEMPLATE_DIR):
        for f in files:
            if f.endswith('.tex'):
                rel = os.path.relpath(os.path.join(root, f), TEMPLATE_DIR)
                templates.append(rel)
    return jsonify({'templates': templates})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
